validation.browserScript:
const root='/home/ubuntu/dev/explorakit';
const req=require('node:module').createRequire(root+'/package.json');
const assert=req('node:assert/strict'),fs=req('node:fs'),http=req('node:http'),{once}=req('node:events'),{randomUUID}=req('node:crypto');
if(!/test/i.test(process.env.DB_TEST_NAME||''))throw Error('Dedicated test database required');
process.env.DB_NAME=process.env.DB_TEST_NAME;process.env.NODE_ENV='test';
const express=req('express'),{Server}=req('socket.io'),{chromium}=req('playwright'),{dbPool:db}=req('./server/config/database');
const dist='/tmp/riftmon-badge-art-dist',out='/tmp/riftmon-badge-art-browser';fs.mkdirSync(out,{recursive:true});
const app=express(),server=http.createServer(app),io=new Server(server);app.use(express.json());app.use('/api',req('./server/http/routes'));app.use(express.static(dist));app.get('*',(_q,r)=>r.sendFile(dist+'/index.html'));io.use(req('./server/http/authMiddleware').authenticateSocket);req('./server/realtime/socketHandler')(io);
let browser,page,userId,passed=false;const errors=[],screens=[];
async function pictures(label){for(const[width,height]of[[320,568],[393,852],[844,390],[1365,900]]){await page.setViewportSize({width,height});await page.evaluate(async width=>{v.showMobileControls=width<=920;await v.$nextTick();v.resizeWorldViewport();},width);await page.waitForTimeout(100);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));const file=label+'-'+width+'.png';await page.screenshot({path:out+'/'+file});screens.push(file);}await page.setViewportSize({width:393,height:852});await page.evaluate(()=>v.showMobileControls=true);}
(async()=>{try{
 server.listen(0,'127.0.0.1');await once(server,'listening');const base='http://127.0.0.1:'+server.address().port;
 const response=await fetch(base+'/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:'badge_art_'+randomUUID(),password:randomUUID(),starterId:7})});assert.equal(response.status,201);const f=await response.json();userId=f.user.id;
 for(const key of req('./server/game/world/mirrorRift').requiredBadges)await db.execute("INSERT INTO player_badges(user_id,badge_key,awarded_at)VALUES(?,?,'2026-01-02 12:00:00')",[userId,key]);
 const [before]=await db.execute('SELECT badge_key,awarded_at FROM player_badges WHERE user_id=?',[userId]);
 browser=await chromium.launch({headless:true,args:['--no-sandbox']});const context=await browser.newContext({viewport:{width:393,height:852},hasTouch:true});await context.addInitScript(s=>{if(location.protocol==='http:')localStorage.setItem('explorakit.user',JSON.stringify(s));},{...f.user,token:f.token});page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));
 await page.goto(base+'/game',{waitUntil:'networkidle'});await page.waitForFunction(()=>{const v=document.querySelector('.game-root')?.__vue__;if(!v?.socket?.connected||v.mapLoading||!v.progressionState?.badges?.length)return false;window.v=v;return true;});await page.evaluate(()=>v.handleMenuAction('badges'));await page.locator('[data-badge-key="lake_badge"]').waitFor();
 const names={lake_badge:'Badge du Sang-Froid',dune_badge:'Badge Dune',bloom_badge:'Badge Illusion',ore_badge:'Badge Noblesse',tide_badge:'Badge Force',summit_badge:'Badge Sommet',violence_badge:'Badge Violence',pardon_badge:'Badge Pardon'};
 for(const[key,name]of Object.entries(names))assert.equal(await page.locator(`[data-badge-key="${key}"] h4`).innerText(),name);
 assert.equal(await page.locator('[data-badge-key="lake_badge"]').getAttribute('data-badge-earned'),'true');
 const colors={bloom_badge:'#8870b4',ore_badge:'#536d9a',tide_badge:'#b76461'};
 for(const[key,color]of Object.entries(colors)){assert.equal(await page.locator(`[data-badge-key="${key}"] .badge-emblem`).evaluate(e=>e.style.getPropertyValue('--badge-color')),color);assert.equal(await page.locator(`[data-badge-key="${key}"]`).getAttribute('data-badge-earned'),'true');}
 await page.evaluate(()=>document.querySelector('.badge-case-scroll').scrollTop=290);await pictures('new-badge-designs');
 await page.setViewportSize({width:1365,height:900});await page.evaluate(()=>v.showMobileControls=false);await page.waitForTimeout(150);await page.locator('[data-badge-key="bloom_badge"]').scrollIntoViewIfNeeded();await page.screenshot({path:out+'/desktop-new-badges.png'});
 for(const key of Object.keys(colors))await page.locator(`[data-badge-key="${key}"] .badge-emblem`).screenshot({path:out+'/'+key+'.png'});
 await page.evaluate(()=>{v.progressionState.badges=v.progressionState.badges.map(b=>['bloom_badge','ore_badge','tide_badge'].includes(b.key)?{...b,earned:false}:b);});await page.waitForTimeout(100);
 for(const key of Object.keys(colors))assert.equal(await page.locator(`[data-badge-key="${key}"] .badge-case-display`).evaluate(e=>getComputedStyle(e).filter),'grayscale(1)');
 await page.screenshot({path:out+'/unearned-new-badges.png'});

 const [after]=await db.execute('SELECT badge_key,awarded_at FROM player_badges WHERE user_id=?',[userId]);assert.deepEqual(after,before);assert.deepEqual(errors,[]);passed=true;const result={names,earnedBadgesAndDatesPreserved:true,colors,unearnedGrayscalePreserved:true,viewports:4,screens,errors};fs.writeFileSync(out+'/results.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));
}finally{if(!passed&&page)await page.screenshot({path:out+'/failure.png'}).catch(()=>{});await browser?.close();await new Promise(r=>io.close(r));await new Promise(r=>setTimeout(r,200));if(userId)await db.execute('DELETE FROM users WHERE id=?',[userId]);await db.end();}})().catch(e=>{console.error(e.stack);process.exitCode=1});
